function whatsappUrl(service){
 const message=service?`Olá, Lucas! Vim pelo site da Borges Infinity e tenho interesse em ${service}. Gostaria de saber mais e solicitar um orçamento.`:'Olá, Lucas! Vim pelo site da Borges Infinity e gostaria de conversar sobre um projeto.';
 return `https://wa.me/5562999012617?text=${encodeURIComponent(message)}`;
}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
