const compactScene=matchMedia('(max-width: 760px)').matches;const vertices=[],faces=[],N=compactScene?72:96,M=compactScene?12:16;function point(t){return [1.52*Math.cos(t),.69*Math.sin(2*t),.27*Math.sin(t)]}for(let i=0;i<N;i++){let t=i/N*Math.PI*2,p=point(t),q=point(t+.001),tx=q[0]-p[0],ty=q[1]-p[1],len=Math.hypot(tx,ty),nx=-ty/len,ny=tx/len;for(let j=0;j<M;j++){let a=j/M*Math.PI*2,r=.255;vertices.push([p[0]+r*Math.cos(a)*nx,p[1]+r*Math.cos(a)*ny,p[2]+r*Math.sin(a)])}}for(let i=0;i<N;i++)for(let j=0;j<M;j++)faces.push([i*M+j,((i+1)%N)*M+j,((i+1)%N)*M+(j+1)%M,i*M+(j+1)%M]);
